import{_ as r,o as a,c as e,a0 as o}from"./chunks/framework.D7EjqxMK.js";const u=JSON.parse('{"title":"模块二 · 核心模块 导读","description":"","frontmatter":{},"headers":[],"relativePath":"08-ros/02_核心模块/README.md","filePath":"08-ros/02_核心模块/README.md"}'),d={name:"08-ros/02_核心模块/README.md"};function l(h,t,n,s,i,c){return a(),e("div",null,[...t[0]||(t[0]=[o('<blockquote><p><strong>在知识图谱中的位置</strong>：模块二 · 核心模块 · 导读 <strong>难度</strong>：模块导读 | <strong>前置知识</strong>：<a href="./../01_基础概念/README.html">模块一 · 基础概念</a></p></blockquote><h1 id="模块二-·-核心模块-导读" tabindex="-1">模块二 · 核心模块 导读 <a class="header-anchor" href="#模块二-·-核心模块-导读" aria-label="Permalink to &quot;模块二 · 核心模块 导读&quot;">​</a></h1><p>本模块是 ROS 2 知识库的<strong>主干</strong>，覆盖机器人开发者日常 90% 的通信与工程操作：从最基础的节点与发布订阅，到服务/动作、参数、坐标变换、QoS、CLI 与 launch、录制回放与调试工具。读完本模块，应能独立完成&quot;搭通信架构 → 写节点 → 调参数 → 对齐坐标 → 调 QoS → 编排部署 → 录制调试&quot;的完整闭环。</p><h2 id="主题总览" tabindex="-1">主题总览 <a class="header-anchor" href="#主题总览" aria-label="Permalink to &quot;主题总览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>编号</th><th>主题</th><th>难度</th><th>一句话简介</th></tr></thead><tbody><tr><td><a href="./01_节点与发布订阅.html">01</a></td><td>节点与发布订阅</td><td>⭐⭐⭐</td><td>Node/Publisher/Subscription/Topic 四件套 + executor/spin 机制 + 完整数据通路</td></tr><tr><td><a href="./02_服务与动作.html">02</a></td><td>服务与动作</td><td>⭐⭐</td><td>Service 一问一答 vs Action 长任务可取消，goal 状态机与取消传播</td></tr><tr><td><a href="./03_参数系统与配置管理.html">03</a></td><td>参数系统与配置管理</td><td>⭐⭐</td><td>declare/get/set、参数回调、launch 注入、动态重配置</td></tr><tr><td><a href="./04_TF2坐标变换.html">04</a></td><td>TF2 坐标变换</td><td>⭐⭐</td><td>TF 树模型、广播/监听、时间戳插值、REP-103 坐标惯例</td></tr><tr><td><a href="./05_QoS与通信机制.html">05</a></td><td>QoS 与通信机制</td><td>⭐⭐</td><td>可靠性/持久性/历史/活性四维 + 兼容矩阵 + 常用预设</td></tr><tr><td><a href="./06_ROS2_CLI与Launch系统.html">06</a></td><td>ROS2 CLI 与 Launch 系统</td><td>⭐⭐⭐</td><td><code>ros2 &lt;verb&gt;</code> 全景 + ros2cli 扩展机制 + launch 编排</td></tr><tr><td><a href="./07_ROSBag2与Rqt调试工具.html">07</a></td><td>ROSBag2 与 rqt 调试工具</td><td>⭐⭐</td><td>录制/回放/存储插件 + rqt 全家桶 + rviz2 关系</td></tr></tbody></table><h2 id="建议学习顺序" tabindex="-1">建议学习顺序 <a class="header-anchor" href="#建议学习顺序" aria-label="Permalink to &quot;建议学习顺序&quot;">​</a></h2><p><strong>01 → 05 → 06 → 02 → 03 → 04 → 07</strong></p><ol><li><strong><a href="./01_节点与发布订阅.html">01 节点与发布订阅</a></strong>：一切通信的基石，先吃透 executor 与数据通路。</li><li><strong><a href="./05_QoS与通信机制.html">05 QoS 与通信机制</a></strong>：紧跟 01，理解&quot;消息丢不丢、后到者拿不拿得到&quot;——它是后续所有通信调试的钥匙。</li><li><strong><a href="./06_ROS2_CLI与Launch系统.html">06 CLI 与 Launch</a></strong>：有了通信基础，学会用命令探查、用 launch 编排部署。</li><li><strong><a href="./02_服务与动作.html">02 服务与动作</a></strong>：补齐请求-响应与长任务两种语义。</li><li><strong><a href="./03_参数系统与配置管理.html">03 参数系统</a></strong>：让系统&quot;可配置、可调优&quot;。</li><li><strong><a href="./04_TF2坐标变换.html">04 TF2 坐标变换</a></strong>：把多传感器数据对齐到同一坐标系。</li><li><strong><a href="./07_ROSBag2与Rqt调试工具.html">07 录制与调试工具</a></strong>：用录制回放 + 可视化工具定位问题，收尾闭环。</li></ol><blockquote><p>说明：04 与 07 顺序可互换；若你正在做导航/建图，可提前读 04。</p></blockquote><h2 id="与模块三-高级话题-的衔接" tabindex="-1">与模块三（高级话题）的衔接 <a class="header-anchor" href="#与模块三-高级话题-的衔接" aria-label="Permalink to &quot;与模块三（高级话题）的衔接&quot;">​</a></h2><p>本模块大量机制在<a href="./../03_高级话题/README.html">模块三 · 高级话题</a>中展开，避免重复：</p><table tabindex="0"><thead><tr><th>本模块主题</th><th>深入方向</th><th>衔接文档</th></tr></thead><tbody><tr><td>01 节点与发布订阅</td><td>executor 内核、callback group、events_executor</td><td><a href="./../03_高级话题/02_线程模型与Executor深度解析.html">执行器与回调组详解</a></td></tr><tr><td>01 / 05</td><td>DDS、RMW 适配层、跨厂商差异</td><td><a href="./../03_高级话题/01_ROS2架构分层详解.html">ROS2 架构详解</a></td></tr><tr><td>04 TF2</td><td>SLAM/导航中 map→odom→base_link 的更新机制</td><td><a href="./../04_工程实践/05_导航与运动控制栈(Nav2_MoveIt2_ros2control).html">导航与运动控制栈</a></td></tr><tr><td>05 QoS</td><td>deadline/lifespan/liveliness 实时性进阶</td><td><a href="./../03_高级话题/01_ROS2架构分层详解.html">架构详解</a></td></tr><tr><td>06 Launch</td><td>lifecycle 节点、composable 组件化动态装载</td><td><a href="./../03_高级话题/README.html">高级话题</a></td></tr></tbody></table><h2 id="版本与来源说明" tabindex="-1">版本与来源说明 <a class="header-anchor" href="#版本与来源说明" aria-label="Permalink to &quot;版本与来源说明&quot;">​</a></h2><ul><li>本模块以 <strong>ROS 2 Jazzy Jalisco（2024-05，LTS）</strong> 为主要参考版本，并覆盖 Kilted Kaiju（2025-05）与 Rolling 的新变化；<strong>Lyrical Luth</strong>（L 系列）已于 2026-05 官方公告发布（✅ 已核实，announcement 线程：<a href="https://discourse.openrobotics.org/t/ros-2-lyrical-luth-released/55021%EF%BC%89%E3%80%82" target="_blank" rel="noreferrer">https://discourse.openrobotics.org/t/ros-2-lyrical-luth-released/55021）。</a></li><li>官方文档基准：<a href="https://docs.ros.org/en/jazzy/" target="_blank" rel="noreferrer">https://docs.ros.org/en/jazzy/</a> ✅</li><li>全部&quot;参考资料&quot; URL 均经 web_search 核验，未核验项已在对应文件标注 <code>⚠️ 待验证</code>，绝无编造链接。</li></ul>',14)])])}const g=r(d,[["render",l]]);export{u as __pageData,g as default};
